// Nodo "Configuración" del flujo "Secretaria · Reiniciar todo": lo que se toca a mano está aquí.
// Este flujo SOLO se lanza a mano (Disparador manual). No lo publiques con ningún disparador automático.

// Los identificadores (no son secretos) se leen del .env del servidor, así se ponen UNA vez para todos los flujos.
// Si una variable no está en el .env, vale lo que esté escrito aquí abajo.
const delEntorno = (clave, porDefecto) => {
  try {
    return String($env[clave] ?? '').trim() || porDefecto;
  } catch (e) {
    return porDefecto;
  }
};

// === Valores fáciles de cambiar ===
// ID del calendario "Secretaria" (Google Calendar > Configuración del calendario > Integrar el calendario > ID). Termina en @group.calendar.google.com.
// Se borran TODOS sus eventos (el calendario en sí se queda).
const CALENDAR_ID = delEntorno('GOOGLE_CALENDAR_ID', 'TU-CALENDARIO@group.calendar.google.com');
// ID de la carpeta "Secretaria" de Drive (el mismo CARPETA_RAIZ_ID del flujo "Sincronizar Drive"). Solo se toca lo que cuelga de ella.
const CARPETA_RAIZ_ID = delEntorno('DRIVE_CARPETA_RAIZ_ID', 'TU-CARPETA-RAIZ');
// Carpetas de la raíz que se conservan (vaciadas por dentro). Todo lo demás de la raíz va a la papelera de Drive.
const CONSERVAR = ['Entrada', 'Notas'];
// SEGURO: mientras esto esté vacío el flujo solo ENSAYA (lista lo que borraría y no toca nada). Para borrar de verdad, escribe exactamente
// BORRAR TODO, ejecuta una vez, y vuelve a dejarlo vacío.
const CONFIRMAR = '';
// ==================================

if (!/^[^@\s/]+@[^@\s/]+$/.test(CALENDAR_ID) || CALENDAR_ID.includes('TU-CALENDARIO')) {
  throw new Error('Configuración: pon el ID del calendario "Secretaria" en CALENDAR_ID (termina en @group.calendar.google.com). Va en el .env del servidor (GOOGLE_CALENDAR_ID=…, y después docker compose up -d)');
}
if (!/^[A-Za-z0-9_-]{10,}$/.test(CARPETA_RAIZ_ID) || CARPETA_RAIZ_ID.includes('TU-CARPETA')) {
  throw new Error('Configuración: pon el ID de la carpeta "Secretaria" de Drive en CARPETA_RAIZ_ID (solo letras, números, guion y guion bajo). Va en el .env del servidor (DRIVE_CARPETA_RAIZ_ID=…, y después docker compose up -d)');
}
if (!Array.isArray(CONSERVAR) || CONSERVAR.some((n) => typeof n !== 'string' || n.trim() === '')) {
  throw new Error('Configuración: CONSERVAR debe ser una lista de nombres de carpeta');
}

return [
  {
    json: {
      config: {
        calendar_id: CALENDAR_ID,
        carpeta_raiz_id: CARPETA_RAIZ_ID,
        conservar: CONSERVAR.map((n) => n.trim()),
        real: CONFIRMAR === 'BORRAR TODO',
      },
    },
  },
];

// Nodo "Planificar raíz": lee lo que cuelga de la carpeta raíz de Drive y decide dos cosas:
//   - qué hijos de la raíz van a la papelera (todo lo que no sea una de las carpetas que se conservan);
//   - qué carpetas conservadas hay que VACIAR: una salida por cada una, con la URL para listar su contenido.
// Nunca borra nada: solo prepara. Las carpetas conservadas se identifican por nombre (sin distinguir mayúsculas ni tildes) y por ser carpetas.

const config = $('Configuración').first().json.config;
const respuesta = $input.first().json;
const hijos = Array.isArray(respuesta?.files) ? respuesta.files : [];

const sinAcentos = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim().toLowerCase();
const CARPETA = 'application/vnd.google-apps.folder';
const conservar = new Set(config.conservar.map(sinAcentos));
const esId = (v) => typeof v === 'string' && /^[A-Za-z0-9_-]{10,}$/.test(v);

const validos = hijos.filter((f) => f && esId(f.id));
const conservadas = validos.filter((f) => f.mimeType === CARPETA && conservar.has(sinAcentos(f.name)));
const paraPapelera = validos.filter((f) => !conservadas.includes(f));

const urlHijos = (idCarpeta) =>
  'https://www.googleapis.com/drive/v3/files?pageSize=1000&supportsAllDrives=true&includeItemsFromAllDrives=true&fields=' +
  encodeURIComponent('nextPageToken,files(id,name,mimeType)') +
  '&q=' +
  encodeURIComponent(`'${idCarpeta}' in parents and trashed=false`);

const comunes = { raiz_incompleta: Boolean(respuesta?.nextPageToken), conservadas_encontradas: conservadas.map((f) => f.name) };

// Una salida por carpeta conservada. Sin ninguna, una salida inocua (listar de nuevo la raíz) para que el flujo siga.
if (conservadas.length === 0) {
  return [{ json: { ...comunes, para_papelera: paraPapelera.map((f) => ({ id: f.id, nombre: f.name })), inocua: true, url: urlHijos(config.carpeta_raiz_id), carpeta: null } }];
}
return conservadas.map((f, i) => ({
  json: {
    ...comunes,
    // La lista de la raíz viaja solo en la primera salida (para no repetirla)
    para_papelera: i === 0 ? paraPapelera.map((x) => ({ id: x.id, nombre: x.name })) : [],
    inocua: false,
    url: urlHijos(f.id),
    carpeta: f.name,
  },
}));

// Nodo "Reunir y decidir": junta todo lo que habría que borrar y lo reparte.
//   - Drive: los hijos de la raíz que no se conservan y el contenido de las carpetas conservadas (a la papelera, no definitivo).
//   - Calendar: todos los eventos del calendario "Secretaria".
// Con CONFIRMAR vacío (modo ensayo) devuelve UN item con el informe y no se borra nada. Con "BORRAR TODO" devuelve una operación por item.
// Si alguna lista venía paginada se avisa (hay más de lo que se ve): se borra lo visto y se vuelve a ejecutar.

const config = $('Configuración').first().json.config;
const plan = $('Planificar raíz').all().map((i) => i.json);
const hijos = $('Leer contenido de las carpetas').all().map((i) => i.json);
const eventosResp = $('Leer eventos de Calendar').first().json;

const MAX_OPERACIONES = 3000;
const ops = [];
const vistos = new Set();
const anadir = (op) => {
  const clave = `${op.tipo}:${op.id}`;
  if (vistos.has(clave) || typeof op.id !== 'string' || op.id === '') return;
  vistos.add(clave);
  ops.push(op);
};

let incompleto = Boolean(plan[0]?.raiz_incompleta);
for (const p of plan) for (const f of p.para_papelera ?? []) anadir({ tipo: 'drive', id: f.id, nombre: f.nombre, donde: 'raíz' });

plan.forEach((p, i) => {
  if (p.inocua) return;
  const r = hijos[i] ?? {};
  if (r.nextPageToken) incompleto = true;
  for (const f of Array.isArray(r.files) ? r.files : []) anadir({ tipo: 'drive', id: f.id, nombre: f.name, donde: p.carpeta });
});

if (eventosResp?.nextPageToken) incompleto = true;
for (const e of Array.isArray(eventosResp?.items) ? eventosResp.items : []) {
  anadir({ tipo: 'calendar', id: e.id, nombre: e.summary || '(sin título)', donde: 'calendario' });
}

if (ops.length > MAX_OPERACIONES) {
  throw new Error(`Reunir y decidir: ${ops.length} operaciones (máximo ${MAX_OPERACIONES} de una vez). Bórralas a mano o divide el trabajo.`);
}

const cuenta = (t) => ops.filter((o) => o.tipo === t).length;
const informe = {
  drive_a_la_papelera: cuenta('drive'),
  eventos_de_calendar: cuenta('calendar'),
  carpetas_conservadas: plan.filter((p) => !p.inocua).map((p) => p.carpeta),
  incompleto,
  nota: incompleto ? 'Alguna lista venía paginada (hay más de lo que se ve): tras borrar, vuelve a ejecutar el flujo hasta que salgan 0.' : null,
};

if (!config.real) {
  return [{ json: { modo: 'ensayo', ...informe, ejemplos: ops.slice(0, 30).map((o) => `${o.tipo === 'drive' ? 'Drive' : 'Calendar'} · ${o.donde} · ${o.nombre}`) } }];
}
if (ops.length === 0) return [{ json: { modo: 'nada', ...informe } }];
return ops.map((o) => ({ json: { modo: 'real', ...o, ...informe } }));

// Nodo "Resumen": deja el resultado en la ejecución. Puede ejecutarse más de una vez (una por rama); la última tiene el recuento completo.
//   Drive: 200 = a la papelera. Calendar: 2xx = borrado; 404/410 = ya no existía (el mismo resultado). Otro estado = fallo (se ve aquí).

const lee = (nombre) => {
  try {
    return $(nombre).all().map((i) => i.json);
  } catch (e) {
    return [];
  }
};
const reunido = lee('Reunir y decidir');
const primero = reunido[0] ?? {};

if (primero.modo === 'ensayo' || primero.modo === 'nada') {
  return [{ json: { ...primero, aviso: primero.modo === 'ensayo' ? 'ENSAYO: no se ha borrado nada. Para borrar de verdad escribe BORRAR TODO en CONFIRMAR (nodo Configuración) y ejecuta de nuevo.' : 'No había nada que borrar.' } }];
}

const operaciones = reunido.filter((r) => r.modo === 'real');
const drive = operaciones.filter((o) => o.tipo === 'drive');
const calendar = operaciones.filter((o) => o.tipo === 'calendar');
const respDrive = lee('Mandar a la papelera de Drive');
const respCalendar = lee('Borrar evento de Calendar');

const bien = (tipo, r) => {
  const s = r?.statusCode;
  return tipo === 'drive' ? s >= 200 && s < 300 : (s >= 200 && s < 300) || s === 404 || s === 410;
};
const fallos = [];
drive.forEach((o, i) => bien('drive', respDrive[i]) || fallos.push(`Drive · ${o.nombre}: ${respDrive[i]?.statusCode ?? 'sin respuesta'}`));
calendar.forEach((o, i) => bien('calendar', respCalendar[i]) || fallos.push(`Calendar · ${o.nombre}: ${respCalendar[i]?.statusCode ?? 'sin respuesta'}`));

return [
  {
    json: {
      modo: 'real',
      drive_a_la_papelera: drive.length - fallos.filter((f) => f.startsWith('Drive')).length,
      eventos_borrados: calendar.length - fallos.filter((f) => f.startsWith('Calendar')).length,
      fallos: fallos.slice(0, 50),
      incompleto: Boolean(primero.incompleto),
      nota: primero.incompleto ? primero.nota : fallos.length > 0 ? 'Hubo fallos: vuelve a ejecutar el flujo (lo ya borrado no se repite).' : 'Hecho. Ahora ejecuta el SQL de vaciar la base de datos si aún no lo has hecho.',
    },
  },
];
